// ... imports remain the same
import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { Play, Pause, Square, Clock, Timer as TimerIcon, Edit3, ArrowLeft, Sword, Shield, AlertCircle, CheckCircle2, TrendingUp, Zap, MessageSquare, Volume2, VolumeX, MonitorOff, ChevronUp, ChevronDown, Award, Gift, Hourglass, FastForward, BookOpen, Flame, Heart, Skull, ScrollText, X, Coins, Sparkles } from 'lucide-react';
import { Proficiency, PhrasePack } from '../types';
import { getEnemyBaseHp, SARCASTIC_QUOTES, TRAINING_QUOTES, ENEMY_MOCKS, PAUSE_QUOTES, formatNumber, RANKS, getRankName } from '../gameData';
import { audio } from '../services/audioService';
import { SupportModal } from './SupportModal';
import { MusicPlayerWidget } from './MusicPlayerWidget';
import { MusicControlModal } from './MusicControlModal';

// ... (Other interfaces remain unchanged) ...
interface TimerProps {
  proficiency: Proficiency;
  autoStart: boolean;
  initialMode?: 'STOPWATCH' | 'TIMER' | 'MANUAL';
  lockMode?: boolean; 
  userAvatar: string;
  onComplete: (durationMinutes: number, notes: string, lootGold: number, wasEarly: boolean) => void;
  onCancel: () => void;
  onUnlockAchievement?: (id: string) => void;
  userLevel: number;
  bonusDmg: number;
  bonusHp: number; 
  bonusHeal: number;
  bonusBlock: number;
  bonusStun: number;
  bonusBarrage: number;
  bonusCrit: number;
  critDmgMultiplier: number; 
  attackSpeed: number; 
  bonusGoldPct: number;
  streakMultiplier?: number;
  gearMultiplier?: number;
  libraryMultiplier?: number;
  speedMultiplier?: number; 
  globalExpMultiplier?: number;
  extraPhrases?: PhrasePack;
  undieableChance?: number;

  // Audio Props
  musicEnabled: boolean;
  onToggleMusic: () => void;
  onSkipMusic: () => void;
}

type TimerMode = 'STOPWATCH' | 'TIMER' | 'MANUAL';

// ... (LocalBattleScene and DamageNumber interfaces remain unchanged) ...
interface DamageNumber {
  id: number;
  value: string | number;
  type: 'normal' | 'crit' | 'overcrit' | 'plus-ultra' | 'glance' | 'enemy' | 'block' | 'heal' | 'stun';
  x: number;
  y: number;
}

interface GoldDrop {
  id: number;
  value: number;
  x: number;
  y: number;
}

interface BattleLogEntry {
  id: string;
  message: string;
  type: 'player' | 'enemy' | 'system' | 'loot';
  timestamp: string;
}

// Helper: Get Enemy Scaling Factors based on Skill Rank
const getEnemyScaling = (level: number) => {
  if (level <= 10) return { scale: 0, undie: 0 }; // Novice
  if (level <= 30) return { scale: 0.025, undie: 0 }; // Apprentice
  if (level <= 60) return { scale: 0.05, undie: 0 }; // Professional
  if (level <= 100) return { scale: 0.10, undie: 2 }; // Expert
  if (level <= 200) return { scale: 0.15, undie: 4 }; // Master
  if (level <= 400) return { scale: 0.20, undie: 6 }; // Grandmaster
  if (level <= 700) return { scale: 0.25, undie: 9 }; // Legend
  if (level <= 999) return { scale: 0.30, undie: 15 }; // Mythic
  return { scale: 0.40, undie: 30 }; // Transcendent
};

// ... (LocalBattleScene updated with VFX) ...
const LocalBattleScene: React.FC<{
  userAvatar: string;
  enemyImage: string;
  enemyHp: number;
  enemyMaxHp: number;
  playerHp: number;
  playerMaxHp: number;
  playerAttackGauge: number; 
  enemyAttackGauge: number; 
  isDead: boolean;
  isUndying: boolean;
  isAttacking: boolean;
  isEnemyAttacking: boolean;
  targetHit: boolean;
  hitVfx: 'crit' | 'overcrit' | 'plus-ultra' | 'revive' | null;
  slashEffect: 'slash-1' | 'slash-2' | null;
  bubbleText: string | null;
  enemyMockText: string | null;
  isEnemyStunned: boolean;
  isPlayerStunned: boolean;
  enableVFX: boolean;
}> = ({ userAvatar, enemyImage, enemyHp, enemyMaxHp, playerHp, playerMaxHp, playerAttackGauge, enemyAttackGauge, isDead, isUndying, isAttacking, isEnemyAttacking, targetHit, hitVfx, slashEffect, bubbleText, enemyMockText, isEnemyStunned, isPlayerStunned, enableVFX }) => {

  // Dynamic class for enemy based on hit type
  let enemyAnimClass = targetHit ? 'brightness-200 saturate-0' : 'animate-idle';

  if (hitVfx === 'crit') enemyAnimClass = 'animate-shake brightness-[5] sepia saturate-200 hue-rotate-[-30deg]'; // Gold/Flash shake
  if (hitVfx === 'overcrit') enemyAnimClass = 'animate-obliterate opacity-80'; // Glitch out
  if (hitVfx === 'plus-ultra') enemyAnimClass = 'opacity-0 transition-opacity duration-300'; // Disappear into void momentarily (simulated by overlay)

  // Camera Shake applied to the wrapper
  const containerShakeClass = hitVfx === 'plus-ultra' ? 'animate-intense-shake' : (hitVfx === 'overcrit' ? 'animate-shake' : '');

  return (
    <div className={`relative w-full h-full overflow-hidden ${containerShakeClass}`}>
      {/* Dynamic Background */}
      <div className="absolute inset-0 bg-[#050b14]">
          <div className={`absolute inset-0 cyber-grid opacity-20 ${enableVFX ? 'animate-grid-move' : ''}`} style={{ transform: 'perspective(500px) rotateX(60deg) translateY(-100px) scale(2)' }}></div>
          <div className="absolute bottom-0 w-full h-1/2 bg-gradient-to-t from-slate-900 via-slate-900/50 to-transparent z-0"></div>

          {/* Plus Ultra: Reality Crack Background Effect */}
          {hitVfx === 'plus-ultra' && enableVFX && (
              <div className="absolute inset-0 bg-white/90 z-0 animate-flash mix-blend-overlay"></div>
          )}

          {/* Death Atmosphere (Red Vignette, World Space) */}
          {isDead && (
              <>
                {/* Subtle vignette only, no text */}
                <div className="absolute inset-0 bg-gradient-to-t from-red-950/60 via-transparent to-black/40 z-0 animate-in fade-in duration-1000"></div>
                {/* Floating Embers */}
                <div className="absolute inset-0 overflow-hidden pointer-events-none">
                    {[...Array(15)].map((_, i) => (
                        <div 
                            key={i} 
                            className="absolute bottom-0 bg-red-500 rounded-full opacity-0 animate-float-up blur-[1px]"
                            style={{
                                width: Math.random() * 4 + 1 + 'px',
                                height: Math.random() * 4 + 1 + 'px',
                                left: Math.random() * 100 + '%',
                                animationDuration: Math.random() * 3 + 2 + 's',
                                animationDelay: Math.random() * 2 + 's'
                            }}
                        />
                    ))}
                </div>
              </>
          )}
      </div>

      {/* Screen Space VFX Layer - ON TOP of everything */}
      {enableVFX && (
        <div className="absolute inset-0 pointer-events-none z-[60] flex items-center justify-center overflow-hidden">

            {/* Standard Crit: Diagonal Flash Slash */}
            {hitVfx === 'crit' && (
                <div className="absolute w-[200%] h-2 bg-yellow-200 rotate-[-45deg] animate-slash-draw shadow-[0_0_20px_#facc15] mix-blend-screen"></div>
            )}

            {/* Overcrit: X-Slash + Glitch Overlay */}
            {hitVfx === 'overcrit' && (
                <>
                    <div className="absolute w-[200%] h-4 bg-red-500 rotate-45 animate-slash-draw shadow-[0_0_30px_#ef4444] mix-blend-lighten" style={{ animationDuration: '0.15s' }}></div>
                    <div className="absolute w-[200%] h-4 bg-purple-500 -rotate-45 animate-slash-draw shadow-[0_0_30px_#a855f7] mix-blend-lighten" style={{ animationDuration: '0.2s', animationDelay: '0.05s' }}></div>
                    <div className="absolute inset-0 bg-red-900/20 mix-blend-overlay animate-flash"></div>
                </>
            )}

            {/* PLUS ULTRA: REALITY SLASH */}
            {hitVfx === 'plus-ultra' && (
                <>
                    {/* The Void Cut */}
                    <div className="absolute h-[200%] w-1 bg-black rotate-[15deg] animate-void-cut shadow-[0_0_50px_#22d3ee] z-50">
                        <div className="absolute inset-0 bg-white blur-md animate-pulse"></div>
                    </div>
                    {/* Screen Shatter Flash */}
                    <div className="absolute inset-0 bg-white animate-flash duration-500 z-40 mix-blend-overlay"></div>
                    <div className="absolute inset-0 bg-cyan-500/30 animate-flash duration-300 z-40 mix-blend-color-dodge"></div>
                    {/* Particle Explosion */}
                    <div className="absolute inset-0 animate-shockwave border-[50px] border-cyan-400/50 rounded-full"></div>
                </>
            )}
        </div>
      )}

      <div className="relative w-full h-full flex items-center justify-between px-8 animate-in fade-in z-10 max-w-4xl mx-auto">

          {/* Player Logic Visuals */}
          <div className={`relative transition-all duration-500 ease-out z-20 ${isAttacking ? 'translate-x-32 scale-110 rotate-3' : (isDead ? 'scale-95 grayscale contrast-125' : 'animate-breathe')}`}>

              {/* Localized YOU DIED Text - SMALLER & POSITIONED */}
              {isDead && (
                  <div className="absolute -top-12 left-1/2 -translate-x-1/2 w-48 text-center z-50 animate-in zoom-in duration-500 pointer-events-none">
                       <h2 className="text-xl font-serif font-bold text-red-600 tracking-widest drop-shadow-[0_2px_4px_rgba(0,0,0,1)] animate-pulse" style={{ textShadow: '0 0 10px rgba(220, 38, 38, 0.8)' }}>
                           YOU DIED
                       </h2>
                       <div className="h-px w-full bg-gradient-to-r from-transparent via-red-600 to-transparent mt-1"></div>
                  </div>
              )}

              {/* 3D Green Magic Circle - LOWERED POSITION */}
              {(isDead || hitVfx === 'revive') && (
                  <div className="absolute -bottom-20 left-1/2 w-48 h-48 pointer-events-none z-10" 
                       style={{ transform: 'translateX(-50%) rotateX(75deg)' }}>
                      <div className="w-full h-full border-[3px] border-emerald-500/60 rounded-full animate-spin-slow shadow-[0_0_20px_rgba(16,185,129,0.4)] flex items-center justify-center">
                           <div className="w-[80%] h-[80%] border-2 border-emerald-400/40 rounded-full border-dashed animate-reverse-spin"></div>
                           <div className="w-[40%] h-[40%] bg-emerald-500/20 rounded-full blur-md animate-pulse"></div>
                      </div>
                  </div>
              )}

              {/* Fantasy Healing VFX Particles (Foreground) */}
              {(isDead || hitVfx === 'revive') && (
                  <div className="absolute inset-0 pointer-events-none z-40 overflow-visible">
                      {/* Rising Light Motes */}
                      {[...Array(8)].map((_, i) => (
                          <div 
                              key={`mote-${i}`}
                              className="absolute bottom-0 left-1/2 bg-emerald-300 w-1 h-1 rounded-full animate-float-up blur-[1px]"
                              style={{
                                  marginLeft: `${(Math.random() * 60) - 30}px`,
                                  animationDuration: `${1.5 + Math.random()}s`,
                                  animationDelay: `${Math.random()}s`,
                                  opacity: 0.7
                              }}
                          />
                      ))}

                      {/* Healing Crosses */}
                      {[...Array(4)].map((_, i) => (
                          <div 
                              key={`cross-${i}`}
                              className="absolute bottom-0 left-1/2 text-emerald-400 text-xs font-bold animate-float-up"
                              style={{
                                  marginLeft: `${(Math.random() * 50) - 25}px`,
                                  animationDuration: `${2 + Math.random()}s`,
                                  animationDelay: `${Math.random() * 1.5}s`,
                                  textShadow: '0 0 5px rgba(16, 185, 129, 0.8)'
                              }}
                          >+</div>
                      ))}
                  </div>
              )}

              <div className={`w-28 h-28 sm:w-36 sm:h-36 rounded-xl border-4 ${isDead ? 'border-red-900 shadow-[0_0_50px_rgba(220,38,38,0.2)]' : 'border-slate-600'} bg-slate-800 overflow-hidden shadow-2xl relative group ring-2 ring-black/50 transition-all duration-500 z-20 ${isDead ? 'rotate-[-5deg] translate-y-4' : ''} ${isUndying ? 'ring-4 ring-yellow-400 shadow-[0_0_30px_rgba(250,204,21,0.5)]' : ''}`}>
                  <img src={userAvatar} className="w-full h-full object-cover pixel-art" alt="Hero" />

                  {/* Death Ghost Effect */}
                  {isDead && (
                      <div className="absolute inset-0 opacity-50 mix-blend-screen animate-pulse" style={{ backgroundImage: `url(${userAvatar})`, backgroundSize: 'cover', transform: 'translateY(-10px) scale(1.1)', filter: 'blur(4px) grayscale(100%)' }}></div>
                  )}

                  <div className={`absolute inset-0 shadow-[inset_0_0_20px_rgba(168,85,247,0.4)] mix-blend-overlay ${isDead ? 'hidden' : ''}`}></div>
                  {isUndying && <div className="absolute inset-0 bg-yellow-500/20 animate-pulse mix-blend-overlay z-30 pointer-events-none"></div>}
                  {isDead && <div className="absolute inset-0 bg-red-900/20 mix-blend-multiply"></div>}
              </div>

              {/* Fantasy Revive Bar (Small, No Text Label, Percentile Only) */}
              {isDead && (
                  <div className="absolute -bottom-10 left-1/2 -translate-x-1/2 flex flex-col items-center justify-center z-50 animate-in fade-in zoom-in duration-300">
                      <div className="relative w-16 h-1.5 bg-slate-900/80 rounded-full border border-emerald-500/30 shadow-[0_0_10px_rgba(16,185,129,0.3)] overflow-hidden">
                          <div 
                              className="h-full bg-gradient-to-r from-emerald-500 via-teal-400 to-white/80 animate-pulse relative"
                              style={{ width: `${(playerHp / playerMaxHp) * 100}%`, transition: 'width 0.3s ease-out' }}
                          >
                              <div className="absolute inset-0 bg-white/40 animate-shimmer"></div>
                          </div>
                      </div>
                      <span className="text-[9px] font-mono font-bold text-emerald-300 mt-1 drop-shadow-md tracking-wider animate-pulse">
                          {Math.floor((playerHp / playerMaxHp) * 100)}%
                      </span>
                  </div>
              )}

              {/* Standard HP Bar (Only when alive) */}
              {!isDead && (
                 <div className="absolute -bottom-5 left-1/2 -translate-x-1/2 w-32 z-50 pointer-events-none">
                     <div className="flex justify-center mb-1 h-4">
                         {isPlayerStunned && <span className="text-[9px] font-bold text-yellow-400 animate-pulse bg-black/50 px-1 rounded border border-yellow-500/50">STUNNED</span>}
                         {isUndying && <span className="text-[9px] font-bold text-yellow-400 animate-pulse bg-black/50 px-1 rounded border border-yellow-500/50 ml-1">UNDYING</span>}
                     </div>
                     <div className="h-3 bg-slate-950 rounded-full border border-emerald-900/50 relative overflow-hidden shadow-lg ring-1 ring-black/50 mb-1">
                         <div 
                             className={`h-full transition-all duration-300 ease-out relative ${playerHp < playerMaxHp * 0.3 ? 'bg-gradient-to-r from-red-600 to-red-500' : 'bg-gradient-to-r from-emerald-600 via-emerald-500 to-teal-500'}`} 
                             style={{ width: `${(playerHp / playerMaxHp) * 100}%` }}
                         ></div>
                         <div className="absolute inset-0 flex items-center justify-center text-[8px] font-mono font-bold text-white/90 tracking-widest drop-shadow-md z-10">
                             {Math.floor(playerHp)} / {Math.floor(playerMaxHp)}
                         </div>
                     </div>
                     <div className="h-1.5 bg-slate-950 rounded-full border border-blue-900/50 relative overflow-hidden shadow">
                         <div className="h-full bg-gradient-to-r from-blue-600 to-cyan-400 transition-all duration-100 ease-linear shadow-[0_0_8px_rgba(34,211,238,0.5)]" style={{ width: `${playerAttackGauge}%` }}></div>
                     </div>
                 </div>
              )}
              {/* Shadow Blob */}
              <div className="w-full h-4 bg-black/60 rounded-[100%] mt-[-10px] blur-md translate-y-4"></div>
          </div>

          {/* Enemy Logic Visuals */}
          <div className={`relative transition-all duration-150 ease-in-out z-20 ${enemyAnimClass} ${isEnemyAttacking ? '-translate-x-40 scale-125 rotate-[-5deg] z-30' : ''}`}>
              <div className="absolute -top-16 left-1/2 -translate-x-1/2 w-32 z-50 pointer-events-none">
                  <div className="flex justify-center mb-1 h-4">
                      {isEnemyStunned && <span className="text-[9px] font-bold text-yellow-400 animate-pulse bg-black/50 px-1 rounded border border-yellow-500/50">STUNNED</span>}
                  </div>
                  <div className="h-3 bg-slate-950 rounded-full border border-red-900/50 relative overflow-hidden shadow-lg shadow-red-900/20 mb-1">
                      <div className="h-full bg-gradient-to-r from-red-800 via-red-600 to-orange-600 transition-all duration-300 ease-out relative" style={{ width: `${(enemyHp / enemyMaxHp) * 100}%` }}></div>
                      <div className="absolute inset-0 flex items-center justify-center text-[8px] font-mono font-bold text-white/90 tracking-widest drop-shadow-md z-10">
                          {formatNumber(Math.floor(enemyHp))} / {formatNumber(Math.floor(enemyMaxHp))}
                      </div>
                  </div>
                  <div className="h-1.5 bg-slate-950 rounded-full border border-red-900/30 relative overflow-hidden shadow">
                      <div className="h-full bg-gradient-to-r from-red-900 to-orange-700 transition-all duration-100 ease-linear" style={{ width: `${enemyAttackGauge}%` }}></div>
                  </div>
              </div>

              {isEnemyAttacking && <div className="absolute inset-0 bg-red-500/20 blur-xl rounded-full scale-150 animate-ping"></div>}
              {/* Hit Impacts */}
              {targetHit && hitVfx === 'plus-ultra' ? null : targetHit && <div className="absolute inset-0 bg-white mix-blend-overlay rounded-full blur-xl opacity-60 animate-impact"></div>}

              {enemyMockText && <div className="absolute -top-32 right-0 bg-red-950/90 text-red-100 text-[10px] font-bold p-3 rounded-2xl rounded-br-none shadow-[0_0_20px_rgba(220,38,38,0.4)] z-50 animate-in zoom-in slide-in-from-bottom-2 w-max max-w-[180px] border border-red-500/50 whitespace-normal leading-tight">{enemyMockText}</div>}

              <div className="w-28 h-28 sm:w-36 sm:h-36 flex items-center justify-center relative">
                  <div className="w-full h-full relative flex items-center justify-center drop-shadow-[0_15px_25px_rgba(0,0,0,0.9)]">
                       <img src={enemyImage || 'https://raw.githubusercontent.com/damarude/PUBLICDAMAR/main/creatures/1-removebg-preview.png'} alt="Enemy" className="w-full h-full object-contain pixel-art" />
                  </div>
              </div>
              <div className="w-full h-4 bg-black/60 rounded-[100%] mt-[-10px] blur-md translate-y-4"></div>
          </div>
      </div>
    </div>
  );
};

export const Timer: React.FC<TimerProps> = ({ 
    proficiency, autoStart, initialMode = 'STOPWATCH', lockMode = false, userAvatar, onComplete, onCancel, onUnlockAchievement,
    userLevel, bonusDmg, bonusHp, bonusHeal, bonusBlock, bonusStun, bonusBarrage, bonusCrit, critDmgMultiplier, attackSpeed = 0, bonusGoldPct = 0, 
    streakMultiplier = 0, gearMultiplier = 0, libraryMultiplier = 0, speedMultiplier = 1, globalExpMultiplier = 1, extraPhrases, undieableChance = 0,
    musicEnabled, onToggleMusic, onSkipMusic
}) => {
  const [setupMode, setSetupMode] = useState<TimerMode>(initialMode);
  const [isSetup, setIsSetup] = useState(!autoStart);
  const [elapsedSeconds, setElapsedSeconds] = useState(0); 
  const [remainingSeconds, setRemainingSeconds] = useState(25 * 60); 
  const [timerDuration, setTimerDuration] = useState(25); 
  const [isActive, setIsActive] = useState(autoStart);
  const [isMuted, setIsMuted] = useState(false);
  const [isScreensaver, setIsScreensaver] = useState(false);
  const [currentQuote, setCurrentQuote] = useState<string>('');
  const [pauseQuote, setPauseQuote] = useState<string>('');
  const [showSupport, setShowSupport] = useState(false);
  const [wasEarlyFinish, setWasEarlyFinish] = useState(false);
  const [showMusicModal, setShowMusicModal] = useState(false);

  // ... (Other state variables) ...
  const [battleLog, setBattleLog] = useState<BattleLogEntry[]>([]);
  const [showBattleLog, setShowBattleLog] = useState(false);
  const [enemyId, setEnemyId] = useState(1);
  const [enemyImage, setEnemyImage] = useState<string>('');
  const [enemyMaxHp, setEnemyMaxHp] = useState(100);
  const [enemyHp, setEnemyHp] = useState(100);
  const [enemyTierGold, setEnemyTierGold] = useState(1);
  const [playerMaxHp, setPlayerMaxHp] = useState(33); 
  const [playerHp, setPlayerHp] = useState(33);
  const [playerAttackGauge, setPlayerAttackGauge] = useState(0);
  const [enemyAttackGauge, setEnemyAttackGauge] = useState(0);
  const [isDead, setIsDead] = useState(false);
  const [isUndying, setIsUndying] = useState(false);
  const [isPlayerStunned, setIsPlayerStunned] = useState(false);
  const [isEnemyStunned, setIsEnemyStunned] = useState(false);
  const [damageNumbers, setDamageNumbers] = useState<DamageNumber[]>([]);
  const [goldDrops, setGoldDrops] = useState<GoldDrop[]>([]);
  const [kills, setKills] = useState(0);
  const [sessionGold, setSessionGold] = useState(0);
  const [bubbleText, setBubbleText] = useState<string | null>(null);
  const [enemyMockText, setEnemyMockText] = useState<string | null>(null);
  const [showConfirm, setShowConfirm] = useState(false);
  const [manualMinutes, setManualMinutes] = useState('30');
  const [isAttacking, setIsAttacking] = useState(false);
  const [isEnemyAttacking, setIsEnemyAttacking] = useState(false); 
  const [targetHit, setTargetHit] = useState(false);
  const [slashEffect, setSlashEffect] = useState<'slash-1' | 'slash-2' | null>(null);
  const [hitVfx, setHitVfx] = useState<'crit' | 'overcrit' | 'plus-ultra' | 'revive' | null>(null);
  const [enableVFX, setEnableVFX] = useState(true);
  const enemySpawnTimeRef = useRef<number>(Date.now());

  const addLog = useCallback((message: string, type: BattleLogEntry['type']) => {
      const entry: BattleLogEntry = {
          id: crypto.randomUUID(),
          message,
          type,
          timestamp: new Date().toLocaleTimeString([], { hour12: false, hour: "2-digit", minute: "2-digit", second: "2-digit" })
      };
      setBattleLog(prev => [entry, ...prev].slice(0, 50));
  }, []);

  // ... (Audio Context Switching) ...
  useEffect(() => {
      // Play random battle track when timer starts
      audio.setPlaylistAndPlay('BATTLE', true);
      return () => {
          // Return to menu playlist (first track usually Level Up My Heart) when leaving
          audio.setPlaylistAndPlay('MENU', false);
      };
  }, []);

  // ... (Init Player HP) ...
  useEffect(() => {
      const baseHealth = 33 + (userLevel * 5);
      const calculatedMaxHp = Math.floor(baseHealth * (1 + ((bonusHp || 0) / 100)));
      setPlayerMaxHp(calculatedMaxHp);
      setPlayerHp(calculatedMaxHp);
  }, [userLevel, bonusHp]);

  // Auto-pause on background
  useEffect(() => {
    const handleVisibilityChange = () => {
      if (document.hidden && isActive) {
        setIsActive(false);
        setPauseQuote("Session auto-paused. Focus lost.");
      }
    };

    document.addEventListener("visibilitychange", handleVisibilityChange);
    return () => {
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, [isActive]);

  // ... (Spawn Enemy logic) ...
  const spawnEnemy = () => {
    let maxEnemyId = 2; 
    const lvl = proficiency.level;
    if (lvl <= 10) maxEnemyId = 2;           
    else if (lvl <= 30) maxEnemyId = 4;      
    else if (lvl <= 60) maxEnemyId = 6;      
    else if (lvl <= 100) maxEnemyId = 8;     
    else if (lvl <= 200) maxEnemyId = 9;     
    else if (lvl <= 400) maxEnemyId = 10;    
    else if (lvl <= 700) maxEnemyId = 12;    
    else maxEnemyId = 13;                    

    const randomId = Math.floor(Math.random() * maxEnemyId) + 1;
    setEnemyId(randomId);
    setEnemyImage(`https://raw.githubusercontent.com/damarude/PUBLICDAMAR/main/creatures/${randomId}-removebg-preview.png`);

    const stats = getEnemyBaseHp(randomId);
    const { scale } = getEnemyScaling(lvl);

    const basePlayerHealth = 33 + (userLevel * 5);
    const calculatedPlayerMaxHp = Math.floor(basePlayerHealth * (1 + ((bonusHp || 0) / 100)));
    const hpFromPlayer = Math.floor(calculatedPlayerMaxHp * scale);

    const exponentialHp = Math.floor(stats.hp + (Math.pow(lvl, 1.2) * 5) + (userLevel * 0.5)) + hpFromPlayer; 
    const scaledGold = Math.floor(stats.baseGold + (lvl * 0.5) + (lvl > 50 ? lvl * 0.1 : 0));

    setEnemyMaxHp(exponentialHp);
    setEnemyHp(exponentialHp);
    setEnemyTierGold(scaledGold);
    setIsEnemyStunned(false);
    setPlayerAttackGauge(0);
    setEnemyAttackGauge(0);
    enemySpawnTimeRef.current = Date.now(); 
  };

  useEffect(() => {
    spawnEnemy();
    const defaultQuotes = TRAINING_QUOTES[proficiency.category] || TRAINING_QUOTES["General"];
    const phrases = extraPhrases?.screensaver && extraPhrases.screensaver.length > 0 
        ? extraPhrases.screensaver 
        : defaultQuotes;

    setCurrentQuote(phrases[Math.floor(Math.random() * phrases.length)]);
    const quoteInterval = setInterval(() => {
        const q = phrases[Math.floor(Math.random() * phrases.length)];
        setCurrentQuote(q);
    }, 30000); 
    return () => clearInterval(quoteInterval);
  }, [proficiency.category, proficiency.level, extraPhrases]);

  // ... (Toggle Mute, Spawn Visual Text) ...
  const toggleMute = () => {
      const newState = !isMuted;
      setIsMuted(newState);
      audio.setMasterMute(newState); 
  };

  const spawnVisualText = (value: string | number, type: DamageNumber['type'], isPlayerTarget: boolean) => {
      const centerX = isPlayerTarget ? 25 : 65; 
      const variation = (Math.random() * 20) - 10;
      const x = Math.max(10, Math.min(90, centerX + variation));
      const y = 45 + (Math.random() * 10 - 5);
      const dmgId = Date.now() + Math.random();
      setDamageNumbers(prev => [...prev, { id: dmgId, value: value, type: type, x: x, y: y }]);
      setTimeout(() => setDamageNumbers(prev => prev.filter(d => d.id !== dmgId)), 1200 / speedMultiplier);
  };

  const totalGlobalMultiplier = useMemo(() => {
      const base = 1;
      return base + streakMultiplier + gearMultiplier + libraryMultiplier;
  }, [streakMultiplier, gearMultiplier, libraryMultiplier]);

  const currentSessionExp = useMemo(() => {
      const minutes = setupMode === 'STOPWATCH' ? elapsedSeconds / 60 : (timerDuration * 60 - remainingSeconds) / 60;
      return Math.floor(minutes * totalGlobalMultiplier);
  }, [elapsedSeconds, remainingSeconds, timerDuration, setupMode, totalGlobalMultiplier]);

  // Game Loop: Timer & Revive
  useEffect(() => {
    let interval: any = null;
    const tickRate = 1000 / speedMultiplier; 
    if (isActive && !showConfirm) {
      interval = setInterval(() => {
        if (setupMode === 'STOPWATCH') setElapsedSeconds(s => s + 1);
        else if (setupMode === 'TIMER') {
          setRemainingSeconds(s => {
            if (s <= 1) {
              clearInterval(interval); setIsActive(false); setShowConfirm(true); setIsScreensaver(false); setWasEarlyFinish(false); audio.playSuccess();
              return 0;
            }
            return s - 1;
          });
        }
        if (isDead && !isUndying) {
            const revivePct = (bonusHeal || 1) / 100;
            const reviveAmount = Math.max(1, Math.floor(playerMaxHp * revivePct));
            setPlayerHp(prev => {
                const nextHp = Math.min(playerMaxHp, prev + reviveAmount);
                if (nextHp >= playerMaxHp) { 
                    setIsDead(false); 
                    spawnVisualText("REVIVED!", "heal", true); 
                    addLog("System rebooted. Soul re-attached.", 'system'); 

                    // Trigger Revive VFX (Local Pillar)
                    setHitVfx('revive');
                    setTimeout(() => setHitVfx(null), 1500);
                } else {
                    spawnVisualText(`+${reviveAmount}`, "heal", true);
                }
                return nextHp;
            });
        }
      }, tickRate);
    }
    return () => clearInterval(interval);
  }, [isActive, setupMode, showConfirm, speedMultiplier, isDead, playerHp, playerMaxHp, bonusHeal, isUndying, addLog]);

  // ... (Combat Callbacks same as before) ...
  const handlePlayerAttack = useCallback(() => {
      if (isDead || isPlayerStunned) return;
      setIsAttacking(true);
      const { scale, undie } = getEnemyScaling(proficiency.level);
      const finalBarrage = Math.min(85, bonusBarrage);
      const finalStun = Math.min(25, bonusStun);
      const enemyBlockChance = bonusBlock * scale;

      setTimeout(() => {
          if (Math.random() * 100 < enemyBlockChance) {
              spawnVisualText("BLOCKED", "block", false); addLog("Enemy blocked your attack!", 'enemy');
              setTimeout(() => { setIsAttacking(false); }, 300 / speedMultiplier); return;
          }
          const missingHpPct = 1 - (playerHp / playerMaxHp);
          const barrageMultiplier = Math.floor(2 + (2 * missingHpPct));
          const isBarrage = Math.random() * 100 < finalBarrage;
          const hitCount = isBarrage ? barrageMultiplier : 1;
          if (isBarrage) { spawnVisualText(`BARRAGE x${hitCount}!`, "crit", false); addLog(`BARRAGE x${hitCount}! Glitch mode active.`, 'player'); }

          let totalDmgDealt = 0;
          for (let i = 0; i < hitCount; i++) {
              const baseDmg = 1 + (userLevel * 0.2) + bonusDmg;
              let finalDmg = baseDmg;
              let dmgType: DamageNumber['type'] = 'normal';
              const roll = Math.random() * 100;
              if (bonusCrit > 200 && roll < (bonusCrit - 200)) { finalDmg *= (critDmgMultiplier * 6); dmgType = 'plus-ultra'; setHitVfx('plus-ultra'); } 
              else if (bonusCrit > 100 && roll < (bonusCrit - 100)) { finalDmg *= (critDmgMultiplier * 4); dmgType = 'overcrit'; setHitVfx('overcrit'); }
              else if (roll < bonusCrit) { finalDmg *= (critDmgMultiplier * 2); dmgType = 'crit'; setHitVfx('crit'); }

              setTimeout(() => setHitVfx(null), 500);
              finalDmg = Math.max(1, Math.floor(finalDmg));
              totalDmgDealt += finalDmg;

              setTimeout(() => {
                  setTargetHit(true); setSlashEffect(Math.random() > 0.5 ? 'slash-1' : 'slash-2');
                  spawnVisualText(Math.floor(finalDmg), dmgType, false);
                  if (speedMultiplier <= 2) audio.playCombatHit();
                  setEnemyAttackGauge(prev => Math.min(100, prev + 20));
              }, i * 100); 
          }
          if (Math.random() * 100 < finalStun && !isEnemyStunned) {
              setIsEnemyStunned(true); spawnVisualText("STUNNED", "stun", false); addLog("Enemy stunned.", 'player');
              setTimeout(() => setIsEnemyStunned(false), 2000 / speedMultiplier);
          }
          setEnemyHp(prev => {
              const newHp = Math.max(0, prev - totalDmgDealt);
              if (newHp === 0) {
                  if (Math.random() * 100 < undie) { spawnVisualText("UNDYING", "plus-ultra", false); addLog("Enemy refuses to die!", "enemy"); return 1; }
                  const killTime = Date.now() - enemySpawnTimeRef.current;
                  if (killTime <= 1500 && onUnlockAchievement) onUnlockAchievement('a53');
                  setKills(k => k + 1);
                  const baseGoldDrop = enemyTierGold;
                  const totalGoldDrop = Math.max(1, Math.floor(baseGoldDrop + (baseGoldDrop * (bonusGoldPct / 100))));
                  setSessionGold(g => g + totalGoldDrop);
                  addLog(`Enemy defeated. Loot: ${totalGoldDrop} G.`, 'loot');
                  const goldId = Date.now() + 1;
                  setGoldDrops(prev => [...prev, { id: goldId, value: totalGoldDrop, x: 50, y: 40 }]);
                  setTimeout(() => setGoldDrops(prev => prev.filter(d => d.id !== goldId)), 1500 / speedMultiplier);
                  setTimeout(() => spawnEnemy(), 500 / speedMultiplier);
              }
              return newHp;
          });
          setTimeout(() => { setIsAttacking(false); setTargetHit(false); setSlashEffect(null); }, (300 + (hitCount * 100)) / speedMultiplier);
      }, 100 / speedMultiplier); 
  }, [bonusBarrage, bonusStun, playerHp, playerMaxHp, userLevel, bonusDmg, bonusCrit, critDmgMultiplier, onUnlockAchievement, isEnemyStunned, speedMultiplier, enemyTierGold, bonusGoldPct, isDead, isPlayerStunned, bonusBlock, addLog]);

  const handleEnemyAttack = useCallback(() => {
      if (isDead || isEnemyStunned) return;
      const finalBlock = Math.min(75, bonusBlock);
      const { scale } = getEnemyScaling(proficiency.level);
      const playerTotalDmg = 1 + (userLevel * 0.2) + bonusDmg;
      setIsEnemyAttacking(true); setTimeout(() => setIsEnemyAttacking(false), 300 / speedMultiplier);

      setTimeout(() => {
          if (Math.random() * 100 < finalBlock) { spawnVisualText("BLOCKED", "block", true); addLog("Blocked!", 'player'); return; }
          const rankIndex = Math.max(0, RANKS.indexOf(getRankName(proficiency.level)));
          const rawDmg = proficiency.level + (playerMaxHp * (0.006 + (rankIndex * 0.0075)));
          const finalEnemyDmg = rawDmg + (playerTotalDmg * scale);
          setPlayerHp(prev => {
              if (isUndying) { spawnVisualText("IMMORTAL", "block", true); return 1; }
              const nextHp = Math.max(0, Math.floor(prev - finalEnemyDmg));
              spawnVisualText(`-${Math.floor(finalEnemyDmg)}`, "enemy", true);
              if (nextHp === 0 && !isDead) {
                  if (undieableChance > 0 && Math.random() * 100 < undieableChance) {
                      setIsUndying(true); spawnVisualText("UNDYING!", "overcrit", true); addLog("Undying activated!", 'system'); audio.playSuccess();
                      setTimeout(() => { setIsUndying(false); setIsDead(true); spawnVisualText("DEFEATED", "overcrit", true); addLog("You died.", 'system'); audio.playError(); }, 4000);
                      return 1;
                  }
                  setIsDead(true); spawnVisualText("DEFEATED", "overcrit", true); addLog("You died.", 'enemy'); audio.playError();
              }
              return nextHp;
          });
      }, 150 / speedMultiplier);
  }, [isDead, isEnemyStunned, bonusBlock, speedMultiplier, proficiency.level, playerMaxHp, isPlayerStunned, isUndying, undieableChance, bonusDmg, bonusCrit, bonusStun, bonusBarrage, userLevel, addLog]);

  // ... (Tick System, UI Functions, Render Screensaver, Render Confirm Modal, Render Setup) ...
  // (Assuming code is preserved as per previous file content, updating only necessary parts)

  useEffect(() => {
    let loop: any = null;
    const TICK_RATE = 50; 
    if (isActive && !showConfirm && (setupMode === 'STOPWATCH' || setupMode === 'TIMER')) {
        loop = setInterval(() => {
            if (!isDead && !isPlayerStunned) {
                const baseInterval = Math.max(500, 2000 / (1 + (attackSpeed / 100)));
                setPlayerAttackGauge(prev => Math.min(100, prev + ((100 / baseInterval) * TICK_RATE * speedMultiplier)));
            }
            if (!isDead && !isEnemyStunned) {
                let baseEnemySpeed = enemyId <= 3 ? 2500 : (enemyId <= 7 ? 1800 : (enemyId <= 10 ? 1200 : 800));
                setEnemyAttackGauge(prev => Math.min(100, prev + ((100 / baseEnemySpeed) * TICK_RATE * speedMultiplier)));
            }
        }, TICK_RATE);
    }
    return () => clearInterval(loop);
  }, [isActive, showConfirm, setupMode, isDead, isPlayerStunned, isEnemyStunned, attackSpeed, speedMultiplier, enemyId]);

  useEffect(() => { if (playerAttackGauge >= 100) { handlePlayerAttack(); setPlayerAttackGauge(0); } }, [playerAttackGauge, handlePlayerAttack]);
  useEffect(() => { if (enemyAttackGauge >= 100) { handleEnemyAttack(); setEnemyAttackGauge(0); } }, [enemyAttackGauge, handleEnemyAttack]);

  const toggle = () => { if (!isActive) audio.playClick(); setIsActive(!isActive); };
  const formatTime = (totalSeconds: number) => {
    const h = Math.floor(totalSeconds / 3600);
    const m = Math.floor((totalSeconds % 3600) / 60);
    const s = totalSeconds % 60;
    return `${h > 0 ? h + ':' : ''}${m < 10 && h > 0 ? '0' : ''}${m}:${s < 10 ? '0' : ''}${s}`;
  };
  const startTimer = () => { audio.playStart(); if (setupMode === 'TIMER') { setRemainingSeconds(timerDuration * 60); } setIsSetup(false); setIsActive(true); };
  const handleStopRequest = () => { setIsActive(false); if (setupMode === 'TIMER' && remainingSeconds > 0) setWasEarlyFinish(true); else setWasEarlyFinish(false); setShowConfirm(true); audio.playClick(); };
  const handleResume = () => { setShowConfirm(false); setIsActive(true); audio.playClick(); };
  const getDurationInMinutes = () => { if (setupMode === 'STOPWATCH') return elapsedSeconds / 60; if (setupMode === 'TIMER') return (timerDuration * 60 - remainingSeconds) / 60; return parseFloat(manualMinutes) || 0; };
  const submitSession = () => { onComplete(getDurationInMinutes(), '', sessionGold, wasEarlyFinish); };

  // ... (Rendering Screensaver, Confirm, Setup are same as previous input) ...

  if (isScreensaver && isActive) {
      return (
          <div onClick={() => setIsScreensaver(false)} className="fixed inset-0 z-50 bg-black flex flex-col items-center justify-center cursor-pointer animate-in fade-in duration-1000">
              <div className="absolute inset-0 cyber-grid opacity-10 animate-grid-move"></div>
              <div className="text-slate-500 text-xs mb-4 uppercase tracking-widest animate-pulse relative z-10">System Status: Training</div>
              <div className="text-8xl font-mono text-purple-500 font-bold select-none drop-shadow-[0_0_25px_rgba(168,85,247,0.5)] relative z-10">{setupMode === 'STOPWATCH' ? formatTime(elapsedSeconds) : formatTime(remainingSeconds)}</div>
              <div className="mt-8 text-slate-400 text-sm font-mono max-w-md text-center px-4 animate-in fade-in duration-1000 relative z-10 italic">{currentQuote && `"${currentQuote}"`}</div>
              <div className="absolute bottom-10 text-slate-600 text-xs animate-bounce">Tap to engage</div>
          </div>
      )
  }

  if (showConfirm || (setupMode === 'MANUAL' && !isSetup)) {
    const duration = setupMode === 'MANUAL' ? (parseFloat(manualMinutes) || 0) : getDurationInMinutes();
    const effectiveMinutes = Math.floor(duration);
    const baseExp = effectiveMinutes * 1; 
    const streakBonusAmount = Math.floor(baseExp * streakMultiplier);
    const gearBonusAmount = Math.floor(baseExp * gearMultiplier);
    const libraryBonusAmount = Math.floor(baseExp * libraryMultiplier);
    const baseWithGlobal = baseExp + streakBonusAmount + gearBonusAmount + libraryBonusAmount;

    let bonusPct = 0; let minReq = 10;
    if (effectiveMinutes >= 120) { bonusPct = 40; minReq = 999; }
    else if (effectiveMinutes >= 60) { bonusPct = 30; minReq = 120; }
    else if (effectiveMinutes >= 30) { bonusPct = 20; minReq = 60; }
    else if (effectiveMinutes >= 10) { bonusPct = 10; minReq = 30; }

    const timeBonusAmount = Math.floor(baseWithGlobal * (bonusPct / 100));
    const totalExp = baseWithGlobal + timeBonusAmount;

    return (
      <div className="flex flex-col h-full justify-center items-center p-6 bg-slate-900/95 backdrop-blur-md fixed inset-0 z-50">
        {showSupport && <SupportModal onClose={() => setShowSupport(false)} />}
        <div className="w-full max-w-sm bg-slate-900 rounded-2xl border-2 border-slate-700 shadow-[0_0_60px_rgba(0,0,0,0.8)] animate-in fade-in zoom-in-95 duration-300 relative overflow-hidden">
          <div className="h-1 bg-gradient-to-r from-transparent via-yellow-500 to-transparent"></div>
          <div className="p-6">
              <div className="text-center mb-6">
                 <h2 className="text-2xl font-rpg font-bold text-white mb-2 tracking-widest uppercase text-shadow-lg">{setupMode === 'MANUAL' ? 'SESSION LOG' : 'MISSION REPORT'}</h2>
                 {wasEarlyFinish && <span className="inline-block px-2 py-0.5 rounded bg-red-900/50 text-red-400 text-[10px] font-bold uppercase mb-2 border border-red-800">Early Termination</span>}
                 <p className="text-slate-400 text-xs italic border-t border-b border-slate-800 py-3 px-4 leading-relaxed">"{pauseQuote}"</p>
              </div>
              <div className="bg-slate-950/50 rounded-xl p-4 border border-slate-800 mb-6 space-y-2">
                 <div className="flex justify-between items-center text-sm mb-2"><span className="text-slate-500 flex items-center gap-2"><Clock size={14}/> Time Elapsed</span><span className="text-white font-mono font-bold">{formatNumber(duration)}m</span></div>
                 <div className="flex justify-between items-center text-sm"><span className="text-slate-500">Base EXP</span><span className="text-white font-mono font-bold">{baseExp}</span></div>
                 {gearBonusAmount > 0 && <div className="flex justify-between items-center text-xs"><span className="text-slate-500 flex items-center gap-1 pl-2"><Gift size={12} className="text-emerald-400"/> Gear Bonus</span><span className="text-emerald-400 font-mono">+{Math.floor(gearBonusAmount)}</span></div>}
                 {streakBonusAmount > 0 && <div className="flex justify-between items-center text-xs"><span className="text-slate-500 flex items-center gap-1 pl-2"><Flame size={12} className="text-orange-400"/> Streak Bonus</span><span className="text-orange-400 font-mono">+{Math.floor(streakBonusAmount)}</span></div>}
                 {timeBonusAmount > 0 && <div className="flex justify-between items-center text-sm"><span className="text-slate-500 flex items-center gap-1"><Hourglass size={14} className="text-purple-400"/> Time Bonus</span><span className="text-purple-400 font-mono font-bold">+{timeBonusAmount}</span></div>}
                 <div className="bg-slate-900 p-3 rounded-lg border border-slate-800/50 mt-3"><div className="flex justify-between items-center"><span className="text-yellow-500 font-bold uppercase text-xs tracking-wider">Total Reward</span><span className="text-2xl text-yellow-400 font-rpg font-bold drop-shadow-md">+{totalExp} XP</span></div>{sessionGold > 0 && <div className="flex justify-between items-center mt-1"><span className="text-slate-600 font-bold uppercase text-[10px] tracking-wider">Loot</span><span className="text-yellow-600 font-mono font-bold text-xs">+{formatNumber(sessionGold)} G</span></div>}</div>
              </div>
              <div className="flex flex-col gap-2">
                  <div className="flex gap-3">
                    {setupMode !== 'MANUAL' && <button onClick={handleResume} className="flex-1 py-3 text-slate-300 font-bold bg-slate-800 hover:bg-slate-700 rounded-xl transition-all border border-slate-700 hover:border-slate-500 text-xs uppercase tracking-wider">Resume</button>}
                    <button onClick={submitSession} className="flex-1 py-3 bg-gradient-to-r from-yellow-600 to-yellow-500 hover:from-yellow-500 hover:to-yellow-400 text-black font-bold rounded-xl shadow-lg shadow-yellow-900/20 transform transition hover:scale-105 text-xs uppercase tracking-wider flex items-center justify-center gap-2"><CheckCircle2 size={16}/> Claim</button>
                  </div>
                  <button onClick={() => setShowSupport(true)} className="w-full py-2 bg-pink-900/30 hover:bg-pink-900/50 border border-pink-500/30 hover:border-pink-500/50 text-pink-400 font-bold rounded-xl transition-all text-[10px] uppercase tracking-wider flex items-center justify-center gap-2"><Heart size={12} className="fill-pink-400" /> Tip The Dev</button>
              </div>
          </div>
        </div>
      </div>
    );
  }

  if (isSetup) {
     return (
      <div className="h-full flex flex-col p-6 max-w-md mx-auto animate-in fade-in slide-in-from-bottom-4">
        <div className="flex items-center gap-4 mb-8"><button onClick={onCancel} className="p-2 hover:bg-slate-800 rounded-full text-slate-400 hover:text-white transition-colors"><ArrowLeft size={24} /></button><h2 className="text-xl font-bold text-white">{lockMode ? (setupMode === 'TIMER' ? 'Timer Setup' : 'Session Setup') : 'Session Setup'}</h2></div>
        {!lockMode && <div className="bg-slate-800 rounded-xl p-2 flex gap-1 mb-8"><button onClick={() => { audio.playSelect(); setSetupMode('STOPWATCH'); }} className={`flex-1 py-2 text-sm font-bold rounded-lg flex items-center justify-center gap-2 transition-all ${setupMode === 'STOPWATCH' ? 'bg-purple-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-700'}`}><Clock size={16} /> Focus</button><button onClick={() => { audio.playSelect(); setSetupMode('TIMER'); }} className={`flex-1 py-2 text-sm font-bold rounded-lg flex items-center justify-center gap-2 transition-all ${setupMode === 'TIMER' ? 'bg-purple-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-700'}`}><TimerIcon size={16} /> Timer</button><button onClick={() => { audio.playSelect(); setSetupMode('MANUAL'); }} className={`flex-1 py-2 text-sm font-bold rounded-lg flex items-center justify-center gap-2 transition-all ${setupMode === 'MANUAL' ? 'bg-purple-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-700'}`}><Edit3 size={16} /> Log</button></div>}
        <div className="flex-1 flex flex-col justify-center">
            {setupMode === 'STOPWATCH' && <div className="text-center"><div className="w-32 h-32 bg-purple-900/20 rounded-full flex items-center justify-center mx-auto mb-6 border-4 border-purple-500/30 relative"><div className="absolute inset-0 rounded-full border-t-4 border-purple-400 animate-spin-slow opacity-50"></div><Play size={48} className="text-purple-400 ml-2" /></div><h3 className="text-xl font-bold mb-2 text-white">Free Flow Mode</h3><p className="text-slate-400 mb-8 px-4">Track your time as you go. Earn bonus EXP for longer sessions.</p><button onClick={startTimer} className="w-full py-4 bg-purple-600 hover:bg-purple-500 text-white font-bold rounded-xl shadow-lg shadow-purple-900/50 transform transition hover:translate-y-[-2px]">Start Focusing</button></div>}
            {setupMode === 'TIMER' && <div className="text-center animate-in fade-in slide-in-from-bottom-2"><div className="mb-8"><div className="w-56 h-56 mx-auto rounded-full bg-slate-900 border-[6px] border-slate-800 flex items-center justify-center relative mb-6 shadow-[0_0_50px_rgba(168,85,247,0.15)] group"><div className="absolute inset-0 rounded-full border-[2px] border-purple-500/30 border-dashed animate-spin-slow"></div><div className="absolute inset-2 rounded-full border-[1px] border-cyan-500/20 animate-reverse-spin"></div><div className="flex flex-col items-center z-10"><span className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-1">Target</span><div className="text-6xl font-mono font-bold text-white tracking-tighter drop-shadow-[0_0_10px_rgba(255,255,255,0.5)]">{timerDuration}</div><span className="text-sm font-bold text-purple-400">MINS</span></div><button onClick={() => setTimerDuration(d => Math.max(5, d - 5))} className="absolute left-[-10px] top-1/2 -translate-y-1/2 p-3 bg-slate-800 rounded-full text-slate-400 hover:text-white border-2 border-slate-700 hover:border-purple-500 transition-colors shadow-lg"><ChevronDown className="rotate-90" size={24}/></button><button onClick={() => setTimerDuration(d => Math.min(180, d + 5))} className="absolute right-[-10px] top-1/2 -translate-y-1/2 p-3 bg-slate-800 rounded-full text-slate-400 hover:text-white border-2 border-slate-700 hover:border-purple-500 transition-colors shadow-lg"><ChevronUp className="rotate-90" size={24}/></button></div></div><div className="grid grid-cols-3 gap-4 mb-8">{[25, 45, 60].map(m => (<button key={m} onClick={() => { audio.playClick(); setTimerDuration(m); }} className={`h-14 rounded-xl font-bold text-sm uppercase tracking-wider transition-all relative overflow-hidden group border-2 ${timerDuration === m ? 'bg-purple-600 border-purple-400 text-white shadow-[0_0_20px_rgba(168,85,247,0.4)] scale-105' : 'bg-slate-800 border-slate-700 text-slate-400 hover:border-slate-500'}`}><span className="relative z-10">{m} Mins</span>{timerDuration === m && <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent animate-shimmer"></div>}</button>))}</div><div className="mb-8 px-4"><input type="range" min="5" max="120" step="5" value={timerDuration} onChange={(e) => setTimerDuration(parseInt(e.target.value))} className="w-full accent-purple-500 bg-slate-800 h-2 rounded-lg appearance-none cursor-pointer" /></div><button onClick={startTimer} className="w-full py-5 bg-gradient-to-r from-purple-600 via-purple-500 to-indigo-600 hover:from-purple-500 hover:to-indigo-500 text-white font-bold rounded-2xl shadow-[0_0_30px_rgba(168,85,247,0.4)] transform transition hover:scale-[1.02] active:scale-[0.98] uppercase tracking-[0.2em] flex items-center justify-center gap-3 border border-purple-400/30"><Zap size={24} className="fill-current animate-pulse"/> <span className="text-lg">Initialize</span></button></div>}
