// Helper: Get Enemy Scaling Factors based on Skill Rank
const getEnemyScaling = (level: number) => {
  if (level <= 10) return { scale: 0, undie: 0 }; // Novice
  if (level <= 30) return { scale: 0.025, undie: 0 }; // Apprentice
  if (level <= 60) return { scale: 0.05, undie: 0 }; // Professional
  if (level <= 100) return { scale: 0.10, undie: 2 }; // Expert
  if (level <= 200) return { scale: 0.15, undie: 4 }; // Master
  if (level <= 400) return { scale: 0.20, undie: 6 }; // Grandmaster
  if (level <= 700) return { scale: 0.25, undie: 9 }; // Legend
  if (level <= 999) return { scale: 0.30, undie: 15 }; // Mythic
  return { scale: 0.40, undie: 30 }; // Transcendent
};

// ... (LocalBattleScene updated with VFX) ...
const LocalBattleScene: React.FC<{
  userAvatar: string;
  enemyImage: string;
  enemyHp: number;
  enemyMaxHp: number;
  playerHp: number;
  playerMaxHp: number;
  playerAttackGauge: number; 
  enemyAttackGauge: number; 
  isDead: boolean;
  isUndying: boolean;
  isEnemyUndying: boolean; // NEW PROP
  isAttacking: boolean;
  isEnemyAttacking: boolean;
  targetHit: boolean;
  hitVfx: 'crit' | 'overcrit' | 'plus-ultra' | 'revive' | null;
  slashEffect: 'slash-1' | 'slash-2' | null;
  bubbleText: string | null;
  enemyMockText: string | null;
  isEnemyStunned: boolean;
  isPlayerStunned: boolean;
  enableVFX: boolean;
}> = ({ userAvatar, enemyImage, enemyHp, enemyMaxHp, playerHp, playerMaxHp, playerAttackGauge, enemyAttackGauge, isDead, isUndying, isEnemyUndying, isAttacking, isEnemyAttacking, targetHit, hitVfx, slashEffect, bubbleText, enemyMockText, isEnemyStunned, isPlayerStunned, enableVFX }) => {

  // Dynamic class for enemy based on hit type
  let enemyAnimClass = targetHit ? 'brightness-200 saturate-0' : 'animate-idle';

  if (hitVfx === 'crit') enemyAnimClass = 'animate-shake brightness-[5] sepia saturate-200 hue-rotate-[-30deg]'; // Gold/Flash shake
  if (hitVfx === 'overcrit') enemyAnimClass = 'animate-obliterate opacity-80'; // Glitch out
  if (hitVfx === 'plus-ultra') enemyAnimClass = 'opacity-0 transition-opacity duration-300'; // Disappear into void momentarily (simulated by overlay)

  // Camera Shake applied to the wrapper
  const containerShakeClass = hitVfx === 'plus-ultra' ? 'animate-intense-shake' : (hitVfx === 'overcrit' ? 'animate-shake' : '');

  return (
    <div className={`relative w-full h-full overflow-hidden ${containerShakeClass}`}>
      {/* Dynamic Background */}
      <div className="absolute inset-0 bg-[#050b14]">
          <div className={`absolute inset-0 cyber-grid opacity-20 ${enableVFX ? 'animate-grid-move' : ''}`} style={{ transform: 'perspective(500px) rotateX(60deg) translateY(-100px) scale(2)' }}></div>
          <div className="absolute bottom-0 w-full h-1/2 bg-gradient-to-t from-slate-900 via-slate-900/50 to-transparent z-0"></div>

          {/* Plus Ultra: Reality Crack Background Effect */}
          {hitVfx === 'plus-ultra' && enableVFX && (
              <div className="absolute inset-0 bg-white/90 z-0 animate-flash mix-blend-overlay"></div>
          )}

          {/* Death Atmosphere (Red Vignette, World Space) */}
          {isDead && (
              <>
                {/* Subtle vignette only, no text */}
                <div className="absolute inset-0 bg-gradient-to-t from-red-950/60 via-transparent to-black/40 z-0 animate-in fade-in duration-1000"></div>
                {/* Floating Embers */}
                <div className="absolute inset-0 overflow-hidden pointer-events-none">
                    {[...Array(15)].map((_, i) => (
                        <div 
                            key={i} 
                            className="absolute bottom-0 bg-red-500 rounded-full opacity-0 animate-float-up blur-[1px]"
                            style={{
                                width: Math.random() * 4 + 1 + 'px',
                                height: Math.random() * 4 + 1 + 'px',
                                left: Math.random() * 100 + '%',
                                animationDuration: Math.random() * 3 + 2 + 's',
                                animationDelay: Math.random() * 2 + 's'
                            }}
                        />
                    ))}
                </div>
              </>
