      </div>

      {/* Screen Space VFX Layer - ON TOP of everything */}
      {enableVFX && (
        <div className="absolute inset-0 pointer-events-none z-[60] flex items-center justify-center overflow-hidden">

            {/* Standard Crit: Diagonal Flash Slash */}
            {hitVfx === 'crit' && (
                <div className="absolute w-[200%] h-2 bg-yellow-200 rotate-[-45deg] animate-slash-draw shadow-[0_0_20px_#facc15] mix-blend-screen"></div>
            )}

            {/* Overcrit: X-Slash + Glitch Overlay */}
            {hitVfx === 'overcrit' && (
                <>
                    <div className="absolute w-[200%] h-4 bg-red-500 rotate-45 animate-slash-draw shadow-[0_0_30px_#ef4444] mix-blend-lighten" style={{ animationDuration: '0.15s' }}></div>
