                    <div className="absolute inset-0 bg-red-900/20 mix-blend-overlay animate-flash"></div>
                </>
            )}

            {/* PLUS ULTRA: REALITY SLASH */}
            {hitVfx === 'plus-ultra' && (
                <>
                    {/* The Void Cut */}
                    <div className="absolute h-[200%] w-1 bg-black rotate-[15deg] animate-void-cut shadow-[0_0_50px_#22d3ee] z-50">
                        <div className="absolute inset-0 bg-white blur-md animate-pulse"></div>
