                  }
                  setIsDead(true); spawnVisualText("DEFEATED", "overcrit", true); addLog("You died.", 'enemy'); audio.playError();
              }
              return nextHp;
          });
      }, 150 / speedMultiplier);
  }, [isDead, isEnemyStunned, bonusBlock, speedMultiplier, proficiency.level, playerMaxHp, isPlayerStunned, isUndying, undieableChance, bonusDmg, bonusCrit, bonusStun, bonusBarrage, userLevel, addLog]);

  // ... (Tick System, UI Functions, Render Screensaver, Render Confirm Modal, Render Setup) ...
